import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n+1)]
    edges = []
    for i in range(n-1):
        x, y = map(int, sys.stdin.readline().split())
        adj[x].append((y, i))
        adj[y].append((x, i))
        edges.append((x, y))

    m = int(sys.stdin.readline())
    queries = []
    for _ in range(m):
        a, b, g = map(int, sys.stdin.readline().split())
        queries.append((a, b, g))

    parent = [0]*(n+1)
    depth = [0]*(n+1)
    visited = [False]*(n+1)
    q = deque([1])
    visited[1] = True
    while q:
        u = q.popleft()
        for v, idx in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                depth[v] = depth[u] + 1
                q.append(v)

    f = [10**6]*(n-1)
    possible = True

    for a, b, g in queries:
        path = []
        u = b
        while u != a:
            path.append(u)
            u = parent[u]
        path.append(a)
        path.reverse()
        min_val = 10**6
        for i in range(len(path)-1):
            u = path[i]
            v = path[i+1]
            for (neighbor, idx) in adj[u]:
                if neighbor == v:
                    if f[idx] < g:
                        f[idx] = g
                    break
        for i in range(len(path)-1):
            u = path[i]
            v = path[i+1]
            for (neighbor, idx) in adj[u]:
                if neighbor == v:
                    if f[idx] < g:
                        possible = False
                    break
        if not possible:
            break

    for a, b, g in queries:
        path = []
        u = b
        while u != a:
            path.append(u)
            u = parent[u]
        path.append(a)
        path.reverse()
        current_min = 10**6
        for i in range(len(path)-1):
            u = path[i]
            v = path[i+1]
            for (neighbor, idx) in adj[u]:
                if neighbor == v:
                    current_min = min(current_min, f[idx])
                    break
        if current_min != g:
            possible = False
            break

    if not possible:
        print(-1)
    else:
        print(' '.join(map(str, f)))

main()
